            ft4->r0 = 30; ft4->g0 = 30;
            ft4->b0 = 34;
            ft4->xy0 = sxy[0];
            ft4->xy1 = sxy[1];
            ft4->xy2 = sxy[3];
            ft4->xy3 = sxy[2];
            f4->xy0 = sxy[0];
            f4->xy1 = sxy[1];
            f4->xy2 = sxy[3];
            f4->xy3 = sxy[2];
            ft4->uv0clut = uv[0].w | clut;
            ft4->uv1tpage = uv[1].w | tpage;
            ft4->uv2 = uv[3].w;
            ft4->uv3 = uv[2].w;
            polys = (unsigned char *)(f4 + 1);
            SetDrawMode(polys, 1, 1, 0x40, 0);
